result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "expiry.py", "content": """"Retention expiry date helper."""
from calendar import monthrange
from datetime import date


def _shift(created: date, months: int) -> tuple[int, int]:
    total = created.year * 12 + (created.month - 1) + months
    return total // 12, total % 12 + 1


def retention_end(created: date, months: int, policy: str) -> date:
    """Return retention end date for a record created on `created`.

    policy:
      anniversary -- same day-of-month, clamped to month end when absent
      month_end   -- last day of the month reached after `months`
    """
    if months < 0:
        raise ValueError("months must be non-negative")
    year, month = _shift(created, months)
    last = monthrange(year, month)[1]
    if policy == "month_end":
        return date(year, month, last)
    if policy == "anniversary":
        return date(year, month, min(created.day, last))
    raise ValueError(f"unknown policy: {policy!r}")


def is_expired(created: date, months: int, policy: str, today: date) -> bool:
    """A record expires the day AFTER its retention_end date."""
    return today > retention_end(created, months, policy)
